BEGIN;
INSERT INTO orders (order_id, total) VALUES (1, 20.00);
SELECT count(*) FROM orders;        -- 1: you see your own uncommitted row
INSERT INTO orders (order_id, total) VALUES (1, 35.00);
-- ERROR: duplicate key value violates unique constraint "orders_pkey"
SELECT count(*) FROM orders;
-- ERROR: current transaction is aborted, commands ignored until end of transaction block
COMMIT;                             -- reports ROLLBACK: order 1 is gone too

BEGIN;
INSERT INTO import_log (msg) VALUES ('batch 42 started');
SAVEPOINT row_17;
INSERT INTO customers (customer_id, email) VALUES (17, 'dup@shop.io');
-- ERROR: duplicate key value violates unique constraint "customers_email_key"
ROLLBACK TO SAVEPOINT row_17;   -- only the failed insert is undone
INSERT INTO import_log (msg) VALUES ('row 17 skipped: duplicate email');
COMMIT;                         -- both log rows are kept

-- The same idea in PL/pgSQL:
DO $$ BEGIN
  BEGIN
    INSERT INTO customers (customer_id, email) VALUES (17, 'dup@shop.io');
  EXCEPTION WHEN unique_violation THEN
    INSERT INTO import_log (msg) VALUES ('row 17 skipped');
  END;
END $$;

