BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance) FROM accounts;   -- the snapshot is taken here
-- ...other sessions commit transfers...
SELECT sum(balance) FROM accounts;   -- same answer: same snapshot
COMMIT;

BEGIN;
SELECT 1;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
-- ERROR: SET TRANSACTION ISOLATION LEVEL must be called before any query
ROLLBACK;

SHOW default_transaction_isolation;  -- read committed

-- (1) atomic, with a guard
UPDATE accounts SET balance = balance - 30
WHERE account_id = 1 AND balance >= 30
RETURNING balance;                 -- no row back = insufficient funds

-- (2) pessimistic
BEGIN;
SELECT balance FROM accounts WHERE account_id = 1 FOR UPDATE;
UPDATE accounts SET balance = 70 WHERE account_id = 1;
COMMIT;

-- (3) optimistic
UPDATE documents SET body = 'v2 text', version = version + 1
WHERE doc_id = 9 AND version = 4;  -- UPDATE 0 = lost the race

-- Fix 1: SERIALIZABLE, and retry the whole transaction on 40001
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM on_call WHERE shift_id = 7 AND active;
UPDATE on_call SET active = false WHERE shift_id = 7 AND doctor = 'ada';
COMMIT;   -- may fail: could not serialize access due to read/write dependencies among transactions

-- Fix 2: make both transactions touch one row
BEGIN;
SELECT 1 FROM shifts WHERE shift_id = 7 FOR UPDATE;   -- the second session waits here
UPDATE on_call SET active = false
WHERE shift_id = 7 AND doctor = 'ada'
  AND (SELECT count(*) FROM on_call WHERE shift_id = 7 AND active) > 1;
COMMIT;

