FOR t IN SELECT * FROM transfers WHERE status = 'pending' ORDER BY transfer_id LOOP
  BEGIN                                    -- savepoint
    UPDATE accounts SET balance = balance - t.amount WHERE account_id = t.from_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'no source'; END IF;   -- 0 rows is not an error
    UPDATE accounts SET balance = balance + t.amount WHERE account_id = t.to_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'no target'; END IF;
    UPDATE transfers SET status = 'done' WHERE transfer_id = t.transfer_id;
  EXCEPTION WHEN check_violation OR raise_exception THEN   -- rolled back to the savepoint
    UPDATE transfers SET status = 'failed' WHERE transfer_id = t.transfer_id;
  END;
END LOOP;

