CREATE TABLE accounts (
  account_id int PRIMARY KEY,
  balance    numeric(10,2) NOT NULL CHECK (balance >= 0)
);
INSERT INTO accounts VALUES (1, 100.00), (2, 20.00);

-- A transfer is two writes that must succeed or fail together
BEGIN;
UPDATE accounts SET balance = balance - 30 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 30 WHERE account_id = 2;
COMMIT;                                   -- 70.00 and 50.00

-- Partial undo: keep the first transfer, drop the second
BEGIN;
UPDATE accounts SET balance = balance - 10 WHERE account_id = 2;
SAVEPOINT second;
UPDATE accounts SET balance = balance - 500 WHERE account_id = 1;
-- ERROR: new row for relation "accounts" violates check constraint "accounts_balance_check"
ROLLBACK TO SAVEPOINT second;             -- the transaction is usable again
UPDATE accounts SET balance = balance + 10 WHERE account_id = 1;
COMMIT;

SELECT account_id, balance FROM accounts ORDER BY account_id;
-- 1 | 80.00
-- 2 | 40.00

